package com.shms.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; private String title; @Column(columnDefinition="TEXT") private String message; @Enumerated(EnumType.STRING) private Type type=Type.INFO; @Column(name="is_read") private Boolean read=false; @Column(name="created_at") private LocalDateTime createdAt; public enum Type{INFO,SUCCESS,WARNING,APPOINTMENT,BILLING,LAB_RESULT,SYSTEM} @PrePersist void pre(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public Type getType(){return type;} public void setType(Type v){type=v;} public Boolean getRead(){return read;} public void setRead(Boolean v){read=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
